all_new=[]
for i,g in enumerate(cases):
 g['collection']='ref1.2';g['source_version']='ref1.1';g.pop('review',None)
 for typ,minimum in [('noul',4),('choice',4),('score',2)]:
  need=max(0,minimum-len(g['questions'][typ]));pool=additions.get(i,{}).get(typ,[])
  assert len(pool)>=need,(i,g['title'],typ,need,len(pool))
  for j,q in enumerate(pool[:need]):
   item={'id':g['id']+'/gen-'+typ+f'-{j+1:02}','type':typ,'title':g['title'],'state':g['state'],'question':q,'original_results':[],'sources':[{'document':'ref1.2/build.py','section':f'Project-authored additions for state {i}','url':None}],'origin':{'kind':'project_authored','author':'Codex','state_source_version':'ref1.1','official_question':False}}
   g['questions'][typ].append(item);all_new.append(item)
  for q in g['questions'][typ]:
   if 'origin' not in q:q['origin']={'kind':'retained_ref1.1','official_question':True}
   if q['id'].find('/gen-')>=0 and q['question']==route:
    q['origin']={'kind':'official_definition_reused','official_question':True,'new_state_pairing':True,'source':'https://docs.typesafe.ai/cookbooks/function_calling'}
   q['historical_results']=q.pop('original_results',[]);q['original_results']=[]
questions=[q for g in cases for vs in g['questions'].values() for q in vs]
assert len(all_new)==493 and len(questions)==812
assert len({q['id'] for q in questions})==812
for g in cases:
 for typ,qs in g['questions'].items():
  for q in qs:
   assert q['state']==g['state']
   if typ=='choice':assert 2<=len(q['question']['criteria'])<=255
   if typ=='score':assert 2<=len(q['question']['criteria'])<=10
summary={'version':'ref1.2','states':66,'original_questions':319,'new_questions':493,'total_questions':812,'by_type':dict(collections.Counter(q['type'] for q in questions)),'source_sha256':hashlib.sha256(src.read_bytes()).hexdigest(),'authorship':'493 new state-question pairs: 480 project-authored, 13 reuse the official tool routing definition; unchanged states and existing question definitions','repeats':5,'model':'jev-1.13.0'}
